//! Protocols generated by [`scan`](crate::scan) and checked in: the core
//! protocol and xdg-shell, enough to put a window on a screen.
//!
//! Each interface is a module holding its message tables (`INTERFACE`), an
//! object type whose methods send its requests, an `Event` enum with a
//! `decode` function, and its enums as constants. Any other protocol is one
//! run of the scanner away; see `examples/scan.rs`.
//!
//! To regenerate after an upstream release, with the XML from
//! <https://gitlab.freedesktop.org/wayland/wayland> (`protocol/wayland.xml`)
//! and <https://gitlab.freedesktop.org/wayland/wayland-protocols>
//! (`stable/xdg-shell/xdg-shell.xml`):
//!
//! ```text
//! cargo run --example scan -- wayland.xml --runtime crate \
//!     --source "wayland.xml, wayland 1.24.0" --out src/protocol/wayland.rs
//! cargo run --example scan -- xdg-shell.xml --runtime crate \
//!     --import crate::protocol::wayland \
//!     --source "xdg-shell.xml, wayland-protocols 1.45" --out src/protocol/xdg_shell.rs
//! ```

/// The core protocol (`wayland.xml`): the display, registry, surfaces,
/// shared-memory buffers, seats and their devices, outputs, data transfer.
#[rustfmt::skip]
pub mod wayland;
/// xdg-shell: toplevel windows and popups.
#[rustfmt::skip]
pub mod xdg_shell;
